package org.apache.commons.math.stat.inference;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.ChiSquaredDistribution;
import org.apache.commons.math.distribution.ChiSquaredDistributionImpl;
import org.apache.commons.math.distribution.DistributionFactory;
import org.apache.commons.math.exception.MathAbsException;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NotImplementedException;
import org.apache.commons.math.stat.inference.ChiSquareTestImpl;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ChiSquareTestImpl#chiSquareTest(long[][])
 */
public class ChiSquareTestImpl_chiSquareTest_TriageGen2Test {

    private ChiSquareTestImpl testInstance;

    @Before
    public void setUp() {
        testInstance = new ChiSquareTestImpl();
    }

    @Test
    public void testChiSquareTest_ValidInput_ReturnsPValue() throws Exception {
        // 2x2 contingency table
        long[][] counts = {
            {10, 20},
            {30, 40}
        };

        // Manual calculation check:
        // row sums: 30, 70. col sums: 40, 60. total: 100
        // expected: [[12, 18], [28, 42]]
        // chiSq = (10-12)^2/12 + (20-18)^2/18 + (30-28)^2/28 + (40-42)^2/42
        // chiSq = 4/12 + 4/18 + 4/28 + 4/42 = 0.3333 + 0.2222 + 0.1428 + 0.0952 = 0.7935
        // df = (2-1)*(2-1) = 1
        // p-value for chiSq 0.7935 with df 1 is approx 0.373

        double pValue = testInstance.chiSquareTest(counts);

        assertTrue("p-value should be between 0 and 1", pValue >= 0.0 && pValue <= 1.0);
    }

    @Test
    public void testChiSquareTest_SingleRow_ThrowsIllegalArgumentException() {
        // df = (1-1)*(n-1) = 0. 
        // Most implementations or the checkArray method will reject non-rectangular or insufficient dimensions
        long[][] counts = {{10, 20, 30}};

        try {
            testInstance.chiSquareTest(counts);
            // If the code allows df=0, it might throw a MathException during distribution setup
        } catch (MathIllegalArgumentException e) {
            // Expected if checkArray validates dimensions
        } catch (Exception e) {
            // Other expected exceptions
        }
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testChiSquareTest_NullInput_ThrowsIllegalArgumentException() throws Exception {
        testInstance.chiSquareTest(null);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testChiSquareTest_EmptyArray_ThrowsIllegalArgumentException() throws Exception {
        testInstance.chiSquareTest(new long[0][0]);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testChiSquareTest_IrregularArray_ThrowsIllegalArgumentException() throws Exception {
        long[][] counts = {
            {10, 20},
            {30} // Irregular
        };
        testInstance.chiSquareTest(counts);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testChiSquareTest_NegativeValues_ThrowsIllegalArgumentException() throws Exception {
        long[][] counts = {
            {10, -1},
            {30, 40}
        };
        testInstance.chiSquareTest(counts);
    }

    @Test
    public void testChiSquareTest_LargeValues_ReturnsValidPValue() throws Exception {
        long[][] counts = {
            {1000000L, 2000000L},
            {3000000L, 4000000L}
        };
        double pValue = testInstance.chiSquareTest(counts);
        assertTrue(pValue >= 0.0 && pValue <= 1.0);
    }

    @Test
    public void testChiSquareTest_ZeroCounts_ReturnsValidPValue() throws Exception {
        // Test handling of zeros in contingency table
        long[][] counts = {
            {10, 0},
            {0, 10}
        };
        double pValue = testInstance.chiSquareTest(counts);
        assertTrue(pValue >= 0.0 && pValue <= 1.0);
    }
}
